-- Applied AFTER isolated synthetic reversal tests. Not a migration.
-- Source-accounting data here is synthetic and contains no customer PII.
ALTER TABLE sport_center.payment_settlement_batches
  ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 7000);
ALTER TABLE sport_center.payment_settlement_items
  ADD COLUMN id bigint GENERATED BY DEFAULT AS IDENTITY,
  ADD COLUMN payment_journal_id integer,
  ADD COLUMN source_event_id uuid,
  ADD COLUMN correlation_id text,
  ADD COLUMN created_by text;
ALTER TABLE sport_center.payment_settlement_configs
  ADD COLUMN fee_tax_inclusive boolean NOT NULL DEFAULT false;

-- Minimal, fictional COA master rows for original owner journal-draft SQL.
-- Account codes mirror the verified CST chart; no actual ledger rows are copied.
CREATE TABLE sport_center.coa_accounts (
  code text PRIMARY KEY, name text NOT NULL,
  account_type text NOT NULL, is_active boolean NOT NULL
);
CREATE TABLE public.chart_of_accounts (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id integer NOT NULL, code text NOT NULL,name text NOT NULL,
  account_category text NOT NULL,account_type text NOT NULL,is_active boolean NOT NULL,
  is_header boolean NOT NULL DEFAULT false,
  is_postable boolean NOT NULL DEFAULT true
);
